from pathlib import Path
import subprocess,time,os,json,runpy
ROOT=Path.cwd(); audit=ROOT/'docs/ux-audit/2026-10-16-round5-reaudit';raw=audit/'raw'
# Wait for the final receipt, not an outer shell PID that can die before its child.
deadline=time.monotonic()+360
while not (raw/'matrix-twoarm-smd.json').exists():
 if time.monotonic()>deadline:raise RuntimeError('Prior native matrix has no final receipt; refusing overlap')
 time.sleep(2)
commands=[]
for family in ['diagnostic','hr','irr']:
 commands.append(('matrix-'+family,['uv','run','python','scripts/run_with_timeout.py','--timeout-seconds','600','--label','native matrix '+family,'--','uv','run','python',str(audit/'native_matrix.py'),family],{}))
for name in ['native_design','native_shell','native_options','native_editor','native_extra']:
 commands.append((name.replace('_','-')+'-serial',['uv','run','python','scripts/run_with_timeout.py','--timeout-seconds','600','--label',name,'--','uv','run','python',str(audit/(name+'.py'))],{}))
for style in ['default','revman','bmj']:
 commands.append(('long-arm-'+style,['uv','run','python',str(raw/'native_long_names.py'),'twoarm-proportion'],{'RCMS_AUDIT_STYLE':style}))
scenarios=runpy.run_path('scripts/verify_rcms.py')['SCENARIOS']
for s in scenarios:
 if s!='doctor':commands.append(('helper-'+s,['uv','run','python','scripts/verify_rcms.py',s,'--native'],{}))
commands.append(('native-scale15',['uv','run','python','scripts/verify_rcms.py','review1-design','--native'],{'QT_SCALE_FACTOR':'1.5'}))
results=[]
for label,command,overrides in commands:
 (raw/'QUEUE-STATE.json').write_text(json.dumps(dict(pid=os.getpid(),active=label,completed=results,total=len(commands)),indent=2))
 env=os.environ.copy();env.update(overrides)
 result=subprocess.run(['uv','run','python',str(audit/'run.py'),label,*command],env=env)
 results.append(dict(label=label,exit_code=result.returncode))
(raw/'QUEUE-STATE.json').write_text(json.dumps(dict(pid=os.getpid(),active=None,completed=results,total=len(commands),finished=True),indent=2))

from pathlib import Path
import subprocess,time,os,json,signal
raw=Path(__file__).resolve().parent;audit=raw.parent;pause=json.loads((raw/'KEYBOARD-PAUSE.json').read_text());end=time.monotonic()+660
while not (raw/(pause['active']+'.json')).exists():
 if time.monotonic()>end:raise RuntimeError('Native predecessor missing; refusing overlap')
 time.sleep(2)
try:
 rc=subprocess.run(['uv','run','python',str(audit/'run.py'),'native-guard-keyboard-replay','uv','run','python','scripts/run_with_timeout.py','--timeout-seconds','300','--label','native guard and keyboard replay','--','uv','run','python',str(raw/'native_guard_keyboard.py')]).returncode
 (raw/'KEYBOARD-REPLAY-STATE.json').write_text(json.dumps(dict(finished=True,exit_code=rc),indent=2))
finally:os.kill(pause['dispatcher_pid'],signal.SIGCONT)

